const out = [];
const inputs = $input.all();
for (let idx = 0; idx < inputs.length; idx++) {
  const j = inputs[idx].json || {};
  let incidents = [];
  if (Array.isArray(j.incidents)) incidents = j.incidents;
  else if (j.incident && typeof j.incident === 'object') incidents = [j.incident];
  else if (j.id) incidents = [j];
  for (const inc of incidents) {
    if (!inc || typeof inc !== 'object') continue;
    out.push({
      json: { incident: inc, incident_id: inc.id ?? null, created_at: inc.created_at ?? null, run_started_ms: Date.now() },
      pairedItem: { item: idx }
    });
  }
}
if (out.length === 0) {
  throw new Error('Normalize Incidents: no incident found in PagerDuty response. Keys: ' + Object.keys(($input.first() || {}).json || {}).join(','));
}
return out;

const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
const windowMs = 10 * 60 * 1000;
for (const k of Object.keys(store.seen)) { if (now - store.seen[k] > windowMs) delete store.seen[k]; }
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const id = j.incident_id || (j.incident && j.incident.id) || null;
  if (!id) { out.push(item); continue; }
  if (store.seen[id] && (now - store.seen[id] < windowMs)) continue; // duplicate within window -> skip
  store.seen[id] = now;
  out.push(item);
}
return out;

const inc = $('Normalize Incidents').item.json.incident || {};
const alerts = $json || {};
const hay = JSON.stringify(alerts) + ' ' + JSON.stringify(inc);
let pid = null, url = null;
let m = hay.match(/[?;&]pid=([A-Za-z0-9_.\-]+)/);
if (m) pid = m[1];
if (!pid) { m = hay.match(/problems?\/problem\/([A-Za-z0-9_.\-]+)/i); if (m) pid = m[1]; }
if (!pid) { m = hay.match(/\/problem\/([A-Za-z0-9_.\-]+)/i); if (m) pid = m[1]; }
const um = hay.match(/https?:\/\/[^"'\s\\]*dynatrace[^"'\s\\]*/i);
if (um) url = um[0];
return { incident_id: $('Normalize Incidents').item.json.incident_id, dt_problem_id: pid || '', dt_problem_url: url || '' };

const linked = $('Get Linked Dynatrace Problem').item.json || {};
const probs = (($('Get Dynatrace Problems').item.json || {}).problems) || [];
const ids = new Set();
function add(arr){ (arr||[]).forEach(e => { const id = e && e.entityId && e.entityId.id; if (id && id.indexOf('SERVICE-') === 0) ids.add(id); }); }
add(linked.affectedEntities);
const rce = linked.rootCauseEntity && linked.rootCauseEntity.entityId && linked.rootCauseEntity.entityId.id;
if (rce && rce.indexOf('SERVICE-') === 0) ids.add(rce);
probs.forEach(p => add(p.affectedEntities));
let _scan = {}; try { _scan = $('Scan Service Health').item.json || {}; } catch (e) { _scan = {}; }
const _scanRecs = (_scan.result && _scan.result.records) || _scan.records || [];
_scanRecs.forEach(r => { const id = r.service_id; const bad = (Number(r.failures)||0) > 0 || (Number(r.errors4xx5xx)||0) > 0; if (id && String(id).indexOf('SERVICE-') === 0 && bad) ids.add(id); });
const arr = Array.from(ids).slice(0, 30);
const dql = arr.length ? arr.map(x => '"' + x + '"').join(', ') : '"SERVICE-NONE"';
return { affected_service_ids: arr, affected_ids_dql: dql, affected_count: arr.length };

