const inc = $('Normalize Incidents').item.json.incident || {};

// ---- Service recognition: is this PagerDuty service one Lumen actually has telemetry for? ----
// GKE enrichment below (Dynatrace, GCP logs, GKE metrics) is hardcoded to YOUR project/cluster via the placeholders above.
// For an incident on an unrecognized PD service, every one of those signals is guaranteed unrelated --
// running the scan anyway just produces confident-sounding noise misattributed as this incident's cause.
// Add your team's PagerDuty service ids here so recognized-service enrichment applies to them.
const KNOWN_PD_SERVICE_IDS = new Set([]); // e.g. new Set(['PXXXXXX', 'PYYYYYY'])
const _pdServiceId = (inc.service && inc.service.id) || null;
const service_recognition = {
  is_recognized_service: KNOWN_PD_SERVICE_IDS.has(_pdServiceId),
  pd_service_id: _pdServiceId,
  pd_service_name: (inc.service && inc.service.summary) || null,
  incident_type: (inc.incident_type && inc.incident_type.name) || null,
  incident_description: inc.description || null
};
const linkedResp = $('Get Linked Dynatrace Problem').item.json || {};
const problemsResp = $('Get Dynatrace Problems').item.json || {};
const deployResp = $('Get Dynatrace Deployments').item.json || {};
const spansResp = $('Get Failing Spans').item.json || {};
const rankResp = (function(){ try { return $('Rank Failing Endpoints').item.json || {}; } catch (e) { return {}; } })();
const rankRecords = (rankResp.result && Array.isArray(rankResp.result.records)) ? rankResp.result.records : [];
// PD past incidents -> recurrence signal (chronic vs novel). Same-service, similar-metadata history.
const pastResp = (function(){ try { return $('Get PD Past Incidents').item.json || {}; } catch (e) { return {}; } })();
const pastList = Array.isArray(pastResp.past_incidents) ? pastResp.past_incidents : [];
const _sigOf = (t) => String(t || '').replace(/^\s*(OPEN|RESOLVED|OPEN Problem|RESOLVED Problem)?\s*Problem\s+P-[0-9]+:\s*/i, '').replace(/\s+/g, ' ').trim();
const _normSig = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim();
const _curSig = _sigOf(inc.title || inc.summary || '');
const _curKey = _normSig(_curSig);
let _recCount = 0, _recFirst = null, _recLast = null;
pastList.forEach(function(pi){
  const it = (pi && pi.incident) || {};
  const sigKey = _normSig(_sigOf(it.title));
  if (_curKey ? (sigKey === _curKey) : true) {
    _recCount++;
    const ts = it.created_at ? new Date(it.created_at).toISOString() : null;
    if (ts) { if (!_recFirst || ts < _recFirst) _recFirst = ts; if (!_recLast || ts > _recLast) _recLast = ts; }
  }
});
const _recSvcId = (inc.service && inc.service.id) || null;
// Tiered on top of the flat `chronic` boolean (kept for BQ/console backward-compat) -- a 3rd and a
// 35th occurrence of the same signature were getting identical full-reanalysis treatment, which is
// the actual "noise": nobody's learned anything new from re-deriving the same root cause every time.
// recurring (3-9): current behavior, full analysis + known-issue framing. chronic (10-24): skip
// re-deriving root cause, state it as established. systemic (25+): same, plus explicit escalation
// framing (standing infra problem, not a fresh incident). See Claude Triage Agent's recurrence block.
const _recTier = _recCount >= 25 ? 'systemic' : _recCount >= 10 ? 'chronic' : _recCount >= 3 ? 'recurring' : null;
const recurrence = pastList.length ? {
  signature: _curSig || null,
  prior_count: _recCount,
  total_returned: pastList.length,
  first_seen: _recFirst,
  last_seen: _recLast,
  chronic: _recCount >= 3,
  tier: _recTier,
  history_url: _recSvcId ? ('https://telusdigital.pagerduty.com/service-directory/' + _recSvcId + '/incidents') : null
} : null;
const problems = Array.isArray(problemsResp.problems) ? problemsResp.problems : [];
const deployments = (deployResp.result && Array.isArray(deployResp.result.records)) ? deployResp.result.records : (Array.isArray(deployResp.events) ? deployResp.events : []);
const spanRecords = (spansResp.result && Array.isArray(spansResp.result.records)) ? spansResp.result.records : (Array.isArray(spansResp.records) ? spansResp.records : []);
const metricsResp = $('Get Service Metrics').item.json || {};
const logsResp = $('Get Error Logs').item.json || {};
const metricRecords = (metricsResp.result && Array.isArray(metricsResp.result.records)) ? metricsResp.result.records : (Array.isArray(metricsResp.records) ? metricsResp.records : []);
const logRecords = Array.isArray(logsResp.entries) ? logsResp.entries : ((logsResp.result && Array.isArray(logsResp.result.records)) ? logsResp.result.records : (Array.isArray(logsResp.records) ? logsResp.records : []));
const topoResp = $('Get Service Topology').item.json || {};
const topoRecords = (topoResp.result && Array.isArray(topoResp.result.records)) ? topoResp.result.records : (Array.isArray(topoResp.records) ? topoResp.records : []);
const eventsResp = $('Get Davis & Change Events').item.json || {};
const eventRecords = (eventsResp.result && Array.isArray(eventsResp.result.records)) ? eventsResp.result.records : (Array.isArray(eventsResp.records) ? eventsResp.records : []);
let healthResp = {}; try { healthResp = $('Scan Service Health').item.json || {}; } catch (e) { healthResp = {}; }
const healthRecords = (healthResp.result && Array.isArray(healthResp.result.records)) ? healthResp.result.records : (Array.isArray(healthResp.records) ? healthResp.records : []);

const serviceFocus = inc.service ? (inc.service.summary || inc.service.name || '') : '';
const focusTokens = String(serviceFocus).toLowerCase().split(/[^a-z0-9]+/).filter(t => t.length >= 3);
let entityTokens = [];
if (linkedResp && linkedResp.problemId) {
  const _names = [ (linkedResp.rootCauseEntity && linkedResp.rootCauseEntity.name) ? linkedResp.rootCauseEntity.name : '' ]
    .concat(Array.isArray(linkedResp.affectedEntities) ? linkedResp.affectedEntities.map(e => e.name) : []);
  entityTokens = _names.join(' ').toLowerCase().split(/[^a-z0-9]+/).filter(t => t.length >= 3);
}
const allFocusTokens = focusTokens.concat(entityTokens);
function isRelevant(obj) {
  const s = JSON.stringify(obj).toLowerCase();
  if (s.indexOf('ccs-ratingprofile') !== -1) return true;
  return allFocusTokens.some(t => s.indexOf(t) !== -1);
}
function curateProblem(p) {
  return {
    displayId: p.displayId,
    problemId: p.problemId,
    title: p.title,
    severity: p.severityLevel,
    status: p.status,
    impact: p.impactLevel,
    startTime: p.startTime,
    rootCauseEntity: (p.rootCauseEntity && p.rootCauseEntity.name) ? p.rootCauseEntity.name : null,
    affectedEntities: Array.isArray(p.affectedEntities) ? p.affectedEntities.map(e => e.name).slice(0, 10) : []
  };
}

// Authoritative problem linked by PagerDuty (if the alert carried a Dynatrace link)
let pagerduty_linked_problem = null;
if (linkedResp && linkedResp.problemId) {
  pagerduty_linked_problem = curateProblem(linkedResp);
  pagerduty_linked_problem.url = 'https://iyc06796.live.dynatrace.com/#problems/problemdetails;pid=' + linkedResp.problemId;
  pagerduty_linked_problem.evidence = ((linkedResp.evidenceDetails && linkedResp.evidenceDetails.details) || []).slice(0, 15).map(x => ({ type: x.evidenceType, name: x.displayName, entity: (x.entity && x.entity.name) || null, rootCauseRelevant: x.rootCauseRelevant === true, details: (((x.data && x.data.properties) || []).filter(pp => typeof pp.value === 'string' && pp.value.length > 0).slice(0, 6).map(pp => ({ key: pp.key, value: String(pp.value).slice(0, 220) }))) }));
  pagerduty_linked_problem.impact = ((linkedResp.impactAnalysis && linkedResp.impactAnalysis.impacts) || []).slice(0, 10).map(x => ({ type: x.impactType, entity: (x.impactedEntity && x.impactedEntity.name) || null, estimatedAffectedUsers: x.estimatedAffectedUsers }));
}

const curatedProblems = problems.slice(0, 30).map(curateProblem);
const curatedDeployments = deployments.slice(0, 40).map(e => ({
  title: e.title || e.name || null,
  eventType: e.type || e.eventType || null,
  startTime: e.timestamp || (e.startTime ? new Date(e.startTime).toISOString() : null),
  entity: e.entity || ((e.entityId && e.entityId.name) ? e.entityId.name : ((e.entityId && e.entityId.entityId) ? e.entityId.entityId : null)),
  properties: e.properties || {}
}));
const curatedSpans = spanRecords.slice(0, 40).map(r => ({
  timestamp: r.timestamp,
  trace_id: r.trace_id,
  endpoint: r.endpoint || r.span_name || null,
  service: r.service || null,
  service_id: r.service_id || null,
  method: r.method || null,
  status_code: r.status_code,
  db_statement: r.db_statement || null,
  failed: r.failed === true,
  duration_ms: (r.duration != null && Number.isFinite(Number(r.duration))) ? Math.round(Number(r.duration) / 1e6) : null, duration_s: (r.duration != null && Number.isFinite(Number(r.duration))) ? Math.round(Number(r.duration) / 1e8) / 10 : null
}));

function focus(list) { const f = list.filter(isRelevant); return f.length ? f : list; }
let dynatrace_problems = focus(curatedProblems).slice(0, 15);
// ensure the PagerDuty-linked problem is present and first
if (pagerduty_linked_problem) {
  dynatrace_problems = dynatrace_problems.filter(p => p.problemId !== pagerduty_linked_problem.problemId);
  dynatrace_problems.unshift(pagerduty_linked_problem);
}
const dynatrace_deployments = focus(curatedDeployments).slice(0, 20);
const failing_spans = focus(curatedSpans).slice(0, 20);
const service_metrics = metricRecords.slice(0, 20);
const _wlOf = (r) => {
  const lb = r.labels || {};
  if (lb.source_canonical_service) return lb.source_canonical_service;
  if (lb.destination_canonical_service) return lb.destination_canonical_service;
  const rl2 = (r.resource && r.resource.labels) || {};
  if (rl2.container_name) return rl2.container_name;
  if (rl2.pod_name) return String(rl2.pod_name).replace(/-[a-z0-9]{6,10}-[a-z0-9]{5}$/, '').replace(/-[0-9]+$/, '');
  return null;
};
const _wlCounts = {};
logRecords.forEach(r => { const w = _wlOf(r); if (w && w !== 'PassthroughCluster' && w !== 'unknown') _wlCounts[w] = (_wlCounts[w] || 0) + 1; });
const error_log_services = Object.keys(_wlCounts).sort((a, b) => _wlCounts[b] - _wlCounts[a]).slice(0, 5);
let error_logs = logRecords.slice(0, 50).map(r => {
  const _lbl = (r.resource && r.resource.labels) || {};
  const _msg = (typeof r.textPayload === 'string') ? r.textPayload : (r.jsonPayload ? (r.jsonPayload.message || r.jsonPayload.msg || JSON.stringify(r.jsonPayload)) : (r.protoPayload ? JSON.stringify(r.protoPayload) : r.content));
  return {
    timestamp: r.timestamp || null,
    level: r.severity || r.loglevel || r.level || null,
    status: (r.jsonPayload && (r.jsonPayload.status || r.jsonPayload.statusCode || r.jsonPayload.status_code)) || r.status || null,
    service: _wlOf(r) || _lbl.namespace_name || r.service || null,
    content: (typeof _msg === 'string') ? _msg.slice(0, 400) : _msg
  };
});
error_logs = (function(l){ const f = l.filter(isRelevant); return f.length ? f : l; })(error_logs).slice(0, 15);
// Error signatures + the IMPACTED APP(S) that emitted them, from the RAW error records (full textPayload
// + labels."k8s-pod/app"). Ties app<->signature so the GCP log link scopes to whatever app is actually
// impacted this incident (not a hardcoded default) AND focuses on the errors triage saw.
const _sigDeny = new Set(['ERROR','SERVICE','BFF','TRACEID','INFO','WARN','DEBUG','HTTP','URL','OTP']);
const _codeSuffix = /_(ERROR|SERVICE|EXCEPTION|FAILED|FAILURE|TIMEOUT|DENIED|INVALID|UNAVAILABLE|NOT_FOUND|DOWNSTREAM)$/;
const _looksLikeCode = t => (t.split('_').length >= 3) || _codeSuffix.test(t);  // drops 2-word names like DANILO_JOSE
const _sigCounts = {};
const _sigApps = {};      // signature -> Set(app)
const _appErrCounts = {}; // app -> error-log count (fallback ranking)
logRecords.forEach(r => {
  const app = (r.labels || {})['k8s-pod/app'] || null;
  if (app) _appErrCounts[app] = (_appErrCounts[app] || 0) + 1;
  const txt = (typeof r.textPayload === 'string') ? r.textPayload
            : (r.jsonPayload ? JSON.stringify(r.jsonPayload) : (typeof r.content === 'string' ? r.content : ''));
  (String(txt).match(/[A-Z][A-Z0-9]*(?:_[A-Z0-9]+)+/g) || []).forEach(tok => {
    if (tok.length >= 6 && !_sigDeny.has(tok) && _looksLikeCode(tok)) {
      _sigCounts[tok] = (_sigCounts[tok] || 0) + 1;
      if (app) { (_sigApps[tok] = _sigApps[tok] || new Set()).add(app); }
    }
  });
});
const error_signatures = Object.keys(_sigCounts).sort((a, b) => _sigCounts[b] - _sigCounts[a]).slice(0, 6);
// Impacted apps = apps that emitted the top signatures; fall back to the top error-emitting apps.
const _impSet = new Set();
error_signatures.forEach(s => (_sigApps[s] || new Set()).forEach(a => _impSet.add(a)));
let impacted_apps = Array.from(_impSet);
if (!impacted_apps.length) {
  impacted_apps = Object.keys(_appErrCounts).sort((a, b) => _appErrCounts[b] - _appErrCounts[a]);
}
impacted_apps = impacted_apps.slice(0, 6);
const topology = topoRecords.slice(0, 60).map(r => ({ id: r.id, service: r.service || r['entity.name'] || null, tags: r.tags || null, calls: r.calls || null, called_by: r.called_by || null }));
let change_events = eventRecords.slice(0, 60).map(r => ({ timestamp: r.timestamp, kind: r.kind, type: r.type, title: r.title, status: r.status, entity: r.entity || null }));
change_events = (function(l){ const f = l.filter(isRelevant); return f.length ? f : l; })(change_events).slice(0, 20);
const _nameMap = {};
(topology || []).forEach(x => { if (x.id && x.service) _nameMap[x.id] = x.service; });
(function(){ function an(arr){ (arr||[]).forEach(e => { const id = e && e.entityId && e.entityId.id; const nm = e && e.name; if (id && nm && !_nameMap[id]) _nameMap[id] = nm; }); } an((linkedResp && linkedResp.affectedEntities) || []); problems.forEach(p => an(p.affectedEntities)); })();
const service_health = healthRecords.slice(0, 30).map(r => ({ service: r.service || _nameMap[r.service_id] || r.service_id, service_id: r.service_id, requests: r.requests, failures: r.failures, errors_4xx_5xx: r.errors4xx5xx, p95_ms: (r.p95 != null && Number.isFinite(Number(r.p95))) ? Math.round(Number(r.p95) / 1e6) : null }));

const culprit = failing_spans.find(s => s.failed) || failing_spans[0] || null;
const dtBase = 'https://iyc06796.apps.dynatrace.com';
const trace_link = (pagerduty_linked_problem && pagerduty_linked_problem.url) ? pagerduty_linked_problem.url : dtBase + '/ui/apps/dynatrace.distributedtraces';
const debug_link = trace_link;
const primary_link = pagerduty_linked_problem ? pagerduty_linked_problem.url : trace_link;

const incident = {
  id: inc.id,
  incident_number: inc.incident_number,
  title: inc.title,
  status: inc.status,
  urgency: inc.urgency,
  priority: (inc.priority && inc.priority.summary) ? inc.priority.summary : null,
  service: serviceFocus,
  created_at: inc.created_at,
  html_url: inc.html_url
};
const dtLive = 'https://iyc06796.live.dynatrace.com';
const svcMap = {};
function collectSvc(arr){ (arr||[]).forEach(e => { const id = e && e.entityId && e.entityId.id; if (id && id.indexOf('SERVICE-') === 0 && !svcMap[id]) svcMap[id] = (e.name || id); }); }
collectSvc((linkedResp && linkedResp.affectedEntities) || []);
problems.forEach(p => collectSvc(p.affectedEntities));
const dtApps = 'https://iyc06796.apps.dynatrace.com';
