    const _inst = _sqlRes ? String(_sqlRes).split(':').slice(-1)[0] : 'ratingprofile';
    addLink('Cloud SQL ' + _inst, 'https://console.cloud.google.com/sql/instances/' + _inst + '/overview?project=' + GCP_PROJECT);
  }
  if (/redis|cache|evicted|blocked/.test(_flags) || /cache|redis/.test(_cat)) {
    addLink('Redis REDIS_NOT_CONFIGURED', 'https://console.cloud.google.com/memorystore/redis/locations/' + REGION + '/instances/REDIS_NOT_CONFIGURED/details/overview?project=' + GCP_PROJECT);
  }
  if (/gke|restart|limit_utilization|\bpod\b|container/.test(_flags)) {
    addLink('GKE cluster', 'https://console.cloud.google.com/kubernetes/clusters/details/' + REGION + '/private-na-ne1-001/details?project=' + GCP_PROJECT);
  }
}

} else {
  // Unrecognized service: no infra correlation is possible, but if the ticket's own service name /
  // description contains a Dynatrace-recognizable entity name, offer it as a clearly-labeled,
  // best-effort/unverified lead (Extract External Search Terms -> Search Dynatrace Entities (External)
  // -> Parse Entity Match). Never presented as authoritative like the recognized-service links above.
  let _match = null;
  try { _match = $('Parse Entity Match').item.json.external_entity_match; } catch (e) {}
  if (_match && _match.id) {
    const _dtUrl = 'https://iyc06796.apps.dynatrace.com/ui/apps/dynatrace.distributedtracing/explorer?filter='
      + encodeURIComponent('dt.entity.service = ' + _match.id).replace(/%20/g, '+');
    addLink('Dynatrace — best-effort match "' + _match.name + '" (unverified, from ticket text)', _dtUrl);
  }
}

// IRIS: TELUS's own incident-management platform's record for this SAME PagerDuty incident --
// always link when matched, regardless of whether it had a usable report (a responder may still
// want to open the room/incident itself).
if (b.iris_web_url) addLink('IRIS incident report' + (b.iris_notes_available ? '' : ' (no report captured yet)'), b.iris_web_url);
// Best-guess runbook (telus/bil-ccs-ratingprofile-gateway) -- always labeled as a guess, never definitive;
// "medium" confidence is a same-family match (e.g. no dedicated playbook for this exact service).
if (b.runbook_suggestion && b.runbook_suggestion.url) {
  const _rb = b.runbook_suggestion;
  addLink('Runbook (best guess' + (_rb.confidence === 'medium' ? ', related service' : '') + '): ' + _rb.service, _rb.url);
}

const _dash = b.looker_dashboard_url || p.looker_dashboard_url;
if (_dash) addLink('Dashboard', _dash);

if (links.length) { L.push(''); L.push('🔗 Links'); links.forEach(x => L.push(x)); }

return { note_content: L.join(nl) };

