const p = $('Parse Triage JSON').first().json;
const b = $('Build Triage Context').first().json;
const inc = b.incident || {};
const lp = b.pagerduty_linked_problem || null;
const S = v => (v == null ? '' : String(v));
const J = v => { try { return JSON.stringify(v == null ? null : v); } catch (e) { return 'null'; } };
const nowIso = new Date().toISOString();
let kbMatchCount = 0; try { kbMatchCount = Number($('Fuse KB Context').first().json.kb_match_count) || 0; } catch (e) { kbMatchCount = 0; }
// feedback-loop / efficiency metrics
const _recDA = b.recurrence || {};
const _priorDA = b.prior_resolution_notes || [];
const _priorCharsDA = _priorDA.reduce(function(a,n){ return a + (n.content ? n.content.length : 0); }, 0);
let _runStartDA = null; try { _runStartDA = Number($('Normalize Incidents').first().json.run_started_ms) || null; } catch (e) {}
const _latencyMsDA = _runStartDA ? (Date.now() - _runStartDA) : null;

// ---- derived metrics for charting ----
const b_slo = b.slo || {};
const scanWide = b_slo.scan_wide;
const scannedServiceCount = b_slo.scanned_service_count;
const metricServiceCount = b_slo.metric_service_count;
const totalRequests = b_slo.total_requests;
const totalFailures = b_slo.total_failures;
const total4xx5xx = b_slo.total_4xx_5xx;
const errorPct = b_slo.error_pct != null ? b_slo.error_pct : null;
const worstLatencyMs = b_slo.worst_p95_ms != null ? b_slo.worst_p95_ms : null;
const p95SloMet = b_slo.p95_slo_met != null ? b_slo.p95_slo_met : null;
const p95SloBasis = b_slo.p95_slo_basis || 'none';
const p95SloThresholdMs = b_slo.p95_slo_threshold_ms != null ? b_slo.p95_slo_threshold_ms : null;
const p95BaselineMs = b_slo.p95_baseline_ms != null ? b_slo.p95_baseline_ms : null;
const P95_SLO_MULT = b_slo.p95_slo_multiplier != null ? b_slo.p95_slo_multiplier : 1;
const _breaches = b_slo.p95_breaches || [];
const keps = b.key_failing_endpoints || [];
const topEp = keps[0] || null;

// ---- rich detail markdown (reused from the former Slack card, tweaked) ----
const sevIcon = ({critical:'🔴', high:'🟠', medium:'🟡', low:'🟢'})[p.severity] || '⚪';
const dq = b.data_quality || {};
const _svcRec = b.service_recognition || {};
const _recognized = _svcRec.is_recognized_service !== false;
const D = [];
D.push('### ' + sevIcon + ' Lumen Auto-Triage — ' + (b.service_focus || 'the service'));
if (!_recognized) D.push('> ⚠️ Unrecognized service (' + (_svcRec.pd_service_name || 'unknown') + ') — infra correlation not applicable; triage based on ticket description only.');
D.push('**Severity:** ' + S(p.severity) + ' · **Confidence:** ' + S(p.confidence) + ' · **Category:** ' + S(p.root_cause_category));
if ((dq.sources_failed || []).length) D.push('> ⚠ Data quality: ' + (dq.sources_ok || 0) + '/' + (dq.sources_total || 0) + ' sources OK — missing: ' + dq.sources_failed.join(', '));
if (p95SloMet != null) { const _s = worstLatencyMs != null ? (worstLatencyMs / 1000).toFixed(1) + 's' : 'n/a'; const _t = p95SloThresholdMs != null ? (p95SloThresholdMs / 1000).toFixed(1) + 's' : 'n/a'; D.push('**SLO p95:** ' + (p95SloMet ? '✅ PASS' : '❌ FAIL') + ' (' + _s + ' vs ' + _t + ' ' + p95SloBasis + ')'); }
if (b.infra && (b.infra.flags || []).length) D.push('**Infra:** ' + b.infra.flags.slice(0, 4).join('; '));
D.push('');
D.push('**Root cause:** ' + (S(p.likely_root_cause) || '—'));
if (p.service_impact) D.push('**Impact:** ' + S(p.service_impact));
if (p.blast_radius) D.push('**Blast radius:** ' + S(p.blast_radius));
const _ns = Array.isArray(p.next_steps) ? p.next_steps : [];
if (_ns.length) { D.push(''); D.push('**Next steps:**'); _ns.slice(0, 3).forEach(x => D.push('- ' + S(x))); }
const _cp = Array.isArray(p.correlated_dynatrace_problem_titles) ? p.correlated_dynatrace_problem_titles : [];
if (_cp.length) D.push('**Correlated problems:** ' + _cp.slice(0, 4).map(S).join('; '));
// Recognized-service-scoped endpoint/Dynatrace data below is only meaningful for a recognized service --
// for a non-recognized one it's unrelated telemetry (same leak this guard fixes in Build PD Note).
const _keps = _recognized ? keps.filter(e => e.url).slice(0, 6) : [];
if (_keps.length) { D.push(''); D.push('**Key failing endpoints** (problem window):'); _keps.forEach(e => D.push('- [' + (e.method ? e.method + ' ' : '') + e.endpoint + (e.status_code ? ' [' + e.status_code + ']' : '') + (e.count > 1 ? ' ×' + e.count : '') + '](' + e.url + ')')); }
// Filtered-out chronic/noise endpoints -- kept visible (not this incident's cause, but not hidden either).
const _noiseDA = (b.excluded_chronic_noise || []).filter(Boolean);
if (_noiseDA.length) { D.push(''); D.push('**Known recurring noise** (not related to this incident): ' + _noiseDA.slice(0, 6).join(', ')); }
const _links = [];
if (_recognized) {
  if (b.problem_url) _links.push('[Dynatrace problem](' + b.problem_url + ')');
} else {
  let _match = null;
  try { _match = $('Parse Entity Match').first().json.external_entity_match; } catch (e) {}
  if (_match && _match.id) {
    const _dtUrl = 'https://iyc06796.apps.dynatrace.com/ui/apps/dynatrace.distributedtracing/explorer?filter='
      + encodeURIComponent('dt.entity.service = ' + _match.id).replace(/%20/g, '+');
    _links.push('[Dynatrace — best-effort match "' + _match.name + '" (unverified)](' + _dtUrl + ')');
  }
}
if (b.iris_web_url) _links.push('[IRIS incident report' + (b.iris_notes_available ? '' : ' (no report yet)') + '](' + b.iris_web_url + ')');
if (b.runbook_suggestion && b.runbook_suggestion.url) {
  const _rbDA = b.runbook_suggestion;
  _links.push('[Runbook (best guess' + (_rbDA.confidence === 'medium' ? ', related service' : '') + '): ' + _rbDA.service + '](' + _rbDA.url + ')');
}
if (inc.html_url) _links.push('[PagerDuty](' + inc.html_url + ')');
if (_links.length) { D.push(''); D.push('**Links:** ' + _links.join(' · ')); }
const detail_markdown = D.join('\n');

// ---- flat Looker / BigQuery-ready row ----
const record = {
  schema_version: 1,
  triage_id: S(inc.id) + '_' + nowIso,
  triaged_at: nowIso,
  source: 'SRE-PagerDutyTriage-v2',

  incident_id: S(inc.id),
  incident_number: S(inc.incident_number),
  incident_title: S(inc.title),
  incident_url: S(inc.html_url),
  incident_status: S(inc.status),
  incident_priority: S(inc.priority),
  incident_urgency: S(inc.urgency),
  incident_created_at: S(inc.created_at),
  service_focus: S(b.service_focus),

  severity: S(p.severity),
  severity_score: Number(p.severity_score) || 0,
  root_cause_category: S(p.root_cause_category),
  likely_root_cause: S(p.likely_root_cause),
  service_impact: S(p.service_impact),
  blast_radius: S(p.blast_radius),
  confidence: S(p.confidence),
  confidence_score: Number(p.confidence_score) || 0,

  linked_problem_id: lp ? S(lp.problemId) : '',
  linked_problem_display_id: lp ? S(lp.displayId) : '',
  linked_problem_title: lp ? S(lp.title) : '',
  problem_url: S(b.problem_url),
  problem_count: Number(b.problem_count) || 0,
  correlated_problem_ids: J(p.correlated_dynatrace_problem_ids || []),
  correlated_problem_titles: J(p.correlated_dynatrace_problem_titles || []),

  top_failing_endpoint: topEp ? S((topEp.method ? topEp.method + ' ' : '') + topEp.endpoint) : '',
  top_failing_status: topEp ? S(topEp.status_code) : '',
  top_failing_url: topEp ? S(topEp.url) : '',
  key_failing_endpoints_json: J(keps),
  failing_span_count: Number(b.failing_span_count) || 0,

  affected_service_count: (b.service_links || []).length,
  deployment_count: Number(b.deployment_count) || 0,
  total_requests: totalRequests,
  total_failures: totalFailures,
  total_4xx_5xx: total4xx5xx,
  error_pct: errorPct == null ? null : Math.round(errorPct * 100) / 100,
  worst_p95_ms: worstLatencyMs,
  p95_baseline_ms: p95BaselineMs,
  p95_slo_threshold_ms: p95SloThresholdMs,
  p95_slo_multiplier: P95_SLO_MULT,
  p95_slo_basis: p95SloBasis,
  p95_slo_met: p95SloMet,
  p95_breaches_json: J(_breaches),
  scan_wide: scanWide,
  scanned_service_count: scannedServiceCount,
  metric_service_count: metricServiceCount,

  next_steps_json: J(p.next_steps || []),
  next_steps_count: (p.next_steps || []).length,
  service_links_json: J(b.service_links || []),

  kb_match_count: kbMatchCount,
  sources_ok: (b.data_quality && b.data_quality.sources_ok != null) ? b.data_quality.sources_ok : null,
  sources_total: (b.data_quality && b.data_quality.sources_total != null) ? b.data_quality.sources_total : null,
  sources_failed_json: J((b.data_quality && b.data_quality.sources_failed) || []),
  infra_saturated: (b.infra && b.infra.saturated) === true,
  infra_flags_json: J((b.infra && b.infra.flags) || []),
  infra_summary_json: J(b.infra || {}),
  detail_markdown: detail_markdown,
  kb_hit: kbMatchCount > 0,
  recurrence_prior_count: _recDA.prior_count != null ? _recDA.prior_count : 0,
  recurrence_chronic: _recDA.chronic === true,
  recurrence_tier: S(_recDA.tier) || null,
  excluded_chronic_noise_json: J(b.excluded_chronic_noise || []),
  recurrence_signature: S(_recDA.signature),
  recurrence_first_seen: S(_recDA.first_seen),
  recurrence_last_seen: S(_recDA.last_seen),
  prior_notes_found: _priorDA.length > 0,
  prior_notes_count: _priorDA.length,
  prior_notes_chars: _priorCharsDA,
  known_issue: p.known_issue === true,
  reused_prior_art: p.reused_prior_art === true,
  triage_latency_ms: _latencyMsDA,
  looker_dashboard_url: '',
  raw_context_json: J(b)
};
return [{ json: record }];

const b = $('Build Triage Context').item.json;
const inc = b.incident || {};
const parts = [];
parts.push(inc.title || '');
parts.push('service: ' + (b.service_focus || ''));
if (b.pagerduty_linked_problem && b.pagerduty_linked_problem.title) parts.push('problem: ' + b.pagerduty_linked_problem.title);
(b.failing_endpoints || []).slice(0,5).forEach(e => parts.push('endpoint: ' + e));
(b.dynatrace_problems || []).slice(0,3).forEach(p => parts.push('dt: ' + (p.title || '')));
(b.error_logs || []).slice(0,3).forEach(l => parts.push('error: ' + (l.content || '')));
const retrieval_text = parts.filter(Boolean).join('\n').slice(0, 2000);
return { retrieval_text, service_focus: b.service_focus || '', incident_id: inc.id || '' };

// Keep only substantive human resolution text: drop Lumen's own notes, process/status notes and link-only notes.
const _PROCESS = [/game ?(day|night)\b.*\b(ended|concluded|complete)/i, /notes? (will be |have been |were )?(captured|published)/i, /scribe agent/i, /triage artifact/i, /closed in dynatrace/i, /already cleared/i];
function cleanNote(c) {
  let s = String(c || '');
  const k = s.indexOf('Lumen Auto-Triage');
  if (k !== -1) s = s.slice(0, k).replace(/[|\s🟢🟡🔴]+$/u, '');
  s = s.trim();
  if (!s) return '';
  const noUrl = s.replace(/https?:\/\/\S+/g, '').replace(/^resolution note:\s*/i, '').trim();
  if (noUrl.length < 30) return '';
  if (_PROCESS.some(function (re) { return re.test(noUrl); }) && noUrl.length < 160) return '';
  return s;
}
let resp = {};
try { resp = $('Retrieve Similar Incidents').item.json || {}; } catch (e) { resp = {}; }
let rows = resp.rows || resp.results || (resp.data && resp.data.rows) || [];
if (!Array.isArray(rows)) rows = [];
const self_id = $('Build Retrieval Text').item.json.incident_id || '';
const norm = (r) => Object.assign({}, r.attributes || {}, r);
const cut = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
// Past records whose resolution was never recorded AND have no root cause carry no signal -- skip them.
const fixOf = (a) => { const w = String(a.resolution_notes || ''); const k = w.indexOf('Lumen Auto-Triage'); return (k === -1 ? w : w.slice(0, k)).split(' | ').map(cleanNote).filter(Boolean).join(' | '); };
const useful = (a) => String(a.likely_root_cause || '').trim() || fixOf(a);
const top = rows.map(norm).filter(a => (a.incident_id || '') !== self_id && useful(a)).slice(0, 3);
const lines = top.map((a, i) => {
  const L = [(i + 1) + '. [' + (a.severity || '?') + '/' + (a.root_cause_category || '?') + '] root cause: ' + cut(a.likely_root_cause || a.text, 260) + (a.incident_url ? ' (' + a.incident_url + ')' : '')];
  const fx = fixOf(a);
  if (fx) {
    L.push('   ACTUAL FIX (human resolution note): ' + cut(fx, 300) + (a.mttr_minutes ? ' [resolved in ' + a.mttr_minutes + ' min]' : ''));
  } else if (a.next_steps) {
    L.push('   predicted next steps (no human fix recorded): ' + cut(Array.isArray(a.next_steps) ? a.next_steps.join(' | ') : a.next_steps, 200));
  }
  return L.join('\n');
});
const kb_fix_count = top.filter(a => fixOf(a)).length;
const kb_context = lines.length ? lines.join('\n') : 'No similar past incidents found in the knowledge base.';
return { kb_context, kb_match_count: top.length, kb_fix_count };

const p = $('Parse Triage JSON').item.json;
const b = $('Build Triage Context').item.json;
const inc = b.incident || {};
if (!(Number(p.confidence_score) > 0) || String(p.severity) === 'unknown') { return []; }
const id = inc.id || ('gen-' + Date.now());
// Fuelix/Turbopuffer namespace 'lumen-incidents' is locked to UINT ids -> the vector id MUST be an
// unsigned integer (sending a string 400s). Use the PagerDuty incident number (stable per incident;
// re-triage overwrites the same KB entry); fall back to a stable hash of the string id.
let _uid = Number(inc.incident_number);
if (!Number.isInteger(_uid) || _uid <= 0) {
  const _s = String(id); let _h = 0;
  for (let i = 0; i < _s.length; i++) { _h = (_h * 31 + _s.charCodeAt(i)) % 9007199254740880; }
  _uid = _h || 1;
}
const _priorNotes = (b.prior_resolution_notes || []).map(function(n){ return n.content; }).filter(Boolean).join(' | ').slice(0, 800);
const _recKB = b.recurrence || {};
const text = [inc.title, 'service: ' + (b.service_focus || ''), 'root cause: ' + (p.likely_root_cause || ''), 'impact: ' + (p.service_impact || ''), 'next steps: ' + ((p.next_steps || []).join(' | ')), (_priorNotes ? 'prior resolution: ' + _priorNotes : '')].filter(Boolean).join('\n').slice(0, 2000);
return {
  row_id: _uid,
  embed_input: text,
  text,
  attrs: {
    incident_id: id,
    service: b.service_focus || '',
    severity: p.severity || 'unknown',
    severity_score: p.severity_score || 0,
    root_cause_category: p.root_cause_category || 'unknown',
    likely_root_cause: p.likely_root_cause || '',
    service_impact: p.service_impact || '',
    next_steps: (p.next_steps || []).join(' | '),
    incident_url: inc.html_url || '',
    created_at: inc.created_at || new Date().toISOString(),
    category: 'incident-triage',
    resolution_notes: _priorNotes,
    recurrence_prior_count: (_recKB.prior_count || 0),
    recurrence_chronic: (_recKB.chronic === true),
    known_issue: (p.known_issue === true),
    reused_prior_art: (p.reused_prior_art === true),
    source: 'lumen'
  }
};

const rec = $('Build KB Record').item.json;
const emb = ($json.data && $json.data[0] && $json.data[0].embedding) || null;
if (!emb) { return []; }
const row = Object.assign({ id: rec.row_id, vector: emb, text: rec.text }, rec.attrs);
const schema = {
  text: { type: 'string', full_text_search: true },
  category: { type: 'string', filterable: true },
  incident_id: { type: 'string', filterable: true },
  service: { type: 'string', filterable: true },
  severity: { type: 'string', filterable: true },
  severity_score: { type: 'float', filterable: true },
  root_cause_category: { type: 'string', filterable: true },
  source: { type: 'string', filterable: true },
  created_at: { type: 'string', filterable: true },
  likely_root_cause: { type: 'string' },
  service_impact: { type: 'string' },
  next_steps: { type: 'string' },
  incident_url: { type: 'string' }
};
return { body: { upsert_rows: [row], distance_metric: 'cosine_distance', schema } };

// Idempotency: only for the AUTOMATIC (webhook) path. Manual re-triage always posts.
let isManual = false;
try { isManual = ($('Prepare Manual Incident').all() || []).length > 0; } catch (e) { isManual = false; }
if (isManual) return $input.all();   // manual re-triage -> always allow, even if a prior note exists

let notes = [];
try {
  const resp = $('Get PD Notes').item.json || {};
  notes = resp.notes || (resp.body && resp.body.notes) || [];
  if (!Array.isArray(notes)) notes = [];
} catch (e) { notes = []; }
const already = notes.some(n => n && typeof n.content === 'string' && n.content.indexOf('Lumen Auto-Triage') !== -1);
if (already) return [];        // webhook duplicate -> skip Post
return $input.all();           // no prior note -> proceed

// GCP Monitoring timeSeries.list allows ONE metric.type per request -> split into one item per metric type.
const PROJECT = "cdo-ccs-ratingprofile-np-e707";
const FILTER = "metric.type = one_of(\"cloudsql.googleapis.com/database/cpu/utilization\",\"cloudsql.googleapis.com/database/memory/utilization\",\"cloudsql.googleapis.com/database/disk/utilization\",\"cloudsql.googleapis.com/database/postgresql/num_backends\",\"cloudsql.googleapis.com/database/postgresql/deadlock_count\") AND resource.labels.database_id = one_of(\"cdo-ccs-ratingprofile-np-e707:ratingprofile\",\"cdo-ccs-ratingprofile-np-e707:ratingprofile\")";
const created = ($('Normalize Incidents').item.json.incident || {}).created_at;
const t0 = created ? Date.parse(created) : Date.now();
const fromIso = new Date(t0 - 30 * 60000).toISOString();
const toIso = new Date(t0 + 15 * 60000).toISOString();
let metricTypes = []; let rest = FILTER;
const m = FILTER.match(/metric\.type\s*=\s*one_of\(([^)]*)\)/i);
if (m) { metricTypes = m[1].split(',').map(s => s.trim().replace(/^["']|["']$/g, '')).filter(Boolean); rest = FILTER.replace(m[0], ''); }
const resourceFilter = rest.replace(/^\s*AND\s*/i, '').replace(/\s*AND\s*$/i, '').trim();
if (!metricTypes.length) { return [{ json: { _noMetrics: true }, pairedItem: { item: 0 } }]; }
return metricTypes.map(mt => ({ json: { metricType: mt, filter: `metric.type = "${mt}"` + (resourceFilter ? ` AND ${resourceFilter}` : ''), project: PROJECT, fromIso, toIso }, pairedItem: { item: 0 } }));

// Re-aggregate per-metric GCP Monitoring responses into one { timeSeries: [...] } for Build Triage Context.
const items = $input.all();
let series = [];
for (const it of items) { const j = it.json || {}; if (Array.isArray(j.timeSeries)) series = series.concat(j.timeSeries); }
return [{ json: { timeSeries: series, ok: true, metricsRequested: items.length }, pairedItem: { item: 0 } }];

// GCP Monitoring timeSeries.list allows ONE metric.type per request -> one item per metric type.
// Impacted-workload scoping, priority order (Davis-curated / evidence-scoped, avoids stale workloads):
//   1) CLOUD_APPLICATION entities named by the linked problem (name == GKE top_level_controller_name)
//   2) SERVICE -> CLOUD_APPLICATION resolved via Dynatrace entities API ('Resolve DT Workloads')
//   3) error-log workloads ONLY when there is NO linked problem at all
//   else -> namespace-scan (scan_wide) within the problem's namespace.
const PROJECT = "cdo-ccs-ratingprofile-np-e707";
const CLUSTER = "private-na-ne1-001";

let problem = {};
try { problem = $('Get Linked Dynatrace Problem').first().json || {}; } catch (e) { problem = {}; }
let q = {};
try { q = $('Build DT Workload Query').first().json || {}; } catch (e) { q = {}; }
const hasLinkedProblem = !!q.hasLinkedProblem;
const cloudAppNames = q.cloudAppNames || [];

let resolved = [];
try {
  const _rdw = $('Resolve DT Workloads').first().json || {};
  const _recs = (_rdw.result && _rdw.result.records) || [];
  const _grail = [].concat(...(_recs.map(r => Array.isArray(r.workloads) ? r.workloads : [])));
  const ents = _rdw.entities || [];
  resolved = _grail.concat(ents.map(e => {
    const t = e.type || (e.entityId && e.entityId.type);
    const nm = e.displayName || e.name;
    return (t === 'CLOUD_APPLICATION' && nm) ? nm : null;
  })).filter(Boolean);
} catch (e) { resolved = []; }

let logWls = [];
if (!hasLinkedProblem) {
  try {
    const _strip = s => String(s).replace(/-[a-z0-9]{6,10}-[a-z0-9]{5}$/, '').replace(/-[0-9]+$/, '');
    const logs = (($('Get Error Logs').first().json || {}).entries) || [];
    const set = new Set();
    logs.forEach(r => {
      const lb = r.labels || {}; const rl = (r.resource && r.resource.labels) || {};
      const w = lb.source_canonical_service || rl.container_name || (rl.pod_name ? _strip(rl.pod_name) : null);
      if (w && w !== 'PassthroughCluster' && w !== 'unknown') set.add(w);
    });
    logWls = Array.from(set);
  } catch (e) { logWls = []; }
}

let workloads = cloudAppNames.length ? cloudAppNames : (resolved.length ? resolved : (hasLinkedProblem ? [] : logWls));
workloads = Array.from(new Set(workloads)).slice(0, 20);
const gkeScoped = workloads.length > 0;
const gkeScopeSource = cloudAppNames.length ? 'dynatrace-cloud-app'
  : (resolved.length ? 'dynatrace-service-resolved'
  : ((!hasLinkedProblem && logWls.length) ? 'error-logs' : 'namespace-scan'));

let namespaces = [];
const _ns = problem['k8s.namespace.name'];
if (Array.isArray(_ns)) namespaces = _ns.filter(Boolean);
else if (typeof _ns === 'string' && _ns) namespaces = [_ns];
if (!namespaces.length) namespaces = ["ccs-ratingprofile", "sapcc-ratingprofile"];

let resourceFilter = `resource.labels.cluster_name="${CLUSTER}" AND resource.labels.namespace_name = one_of(${namespaces.map(n => `"${n}"`).join(',')})`;
if (gkeScoped) {
  resourceFilter += ` AND metadata.system_labels.top_level_controller_name = one_of(${workloads.map(w => `"${w}"`).join(',')})`;
}

const created = ($('Normalize Incidents').first().json.incident || {}).created_at;
const t0 = created ? Date.parse(created) : Date.now();
const fromIso = new Date(t0 - 30 * 60000).toISOString();
const toIso = new Date(t0 + 15 * 60000).toISOString();
const METRICS = [
  { mt: "kubernetes.io/container/cpu/limit_utilization",    aligner: "ALIGN_MEAN",  reducer: "REDUCE_MAX", alignmentPeriod: "300s" },
  { mt: "kubernetes.io/container/memory/limit_utilization", aligner: "ALIGN_MEAN",  reducer: "REDUCE_MAX", alignmentPeriod: "300s" },
  { mt: "kubernetes.io/container/restart_count",            aligner: "ALIGN_DELTA", reducer: "REDUCE_SUM", alignmentPeriod: "2700s" }
];
return METRICS.map(x => ({ json: { metricType: x.mt, filter: `metric.type = "${x.mt}" AND ${resourceFilter}`, project: PROJECT, fromIso, toIso, aligner: x.aligner, reducer: x.reducer, alignmentPeriod: x.alignmentPeriod, gkeScoped, gkeWorkloads: workloads, gkeNamespaces: namespaces, gkeScopeSource }, pairedItem: { item: 0 } }));

// Re-aggregate per-metric GCP Monitoring responses into one { timeSeries: [...] } for Build Triage Context.
const items = $input.all();
let series = [];
for (const it of items) { const j = it.json || {}; if (Array.isArray(j.timeSeries)) series = series.concat(j.timeSeries); }
return [{ json: { timeSeries: series, ok: true, metricsRequested: items.length }, pairedItem: { item: 0 } }];

// Aggregate Kubernetes scheduling/lifecycle events (Cloud Logging k8s_event) into per-reason rollups.
// Catches ImagePullBackOff / Init:CrashLoopBackOff / FailedScheduling etc - failures where the pod
// never starts, so they carry no APM signal (no Dynatrace problem, flat restart_count/CPU/memory).
let resp = {};
try { resp = $('Get GKE Pod Events').first().json || {}; } catch (e) { resp = {}; }
const entries = Array.isArray(resp.entries) ? resp.entries : [];

function stripPodSuffix(s) {
  return String(s).replace(/-[a-z0-9]{6,10}-[a-z0-9]{5}$/, '').replace(/-[0-9]+$/, '');
}
function extractImage(msg) {
  const m = String(msg || '').match(/(?:pulling|pull) image \"([^\"]+)\"/i) || String(msg || '').match(/image \"([^\"]+)\"/i);
  return m ? m[1] : null;
}

const byReason = {};
entries.forEach(e => {
  const jp = e.jsonPayload || {};
  const reason = jp.reason || 'Unknown';
  const involved = jp.involvedObject || {};
  const podName = involved.kind === 'Pod' ? involved.name : null;
  const image = extractImage(jp.message);
  if (!byReason[reason]) byReason[reason] = { reason, count: 0, pods: new Set(), workloads: new Set(), images: new Set(), sample_message: jp.message || null };
  const r = byReason[reason];
  r.count++;
  if (podName) { r.pods.add(podName); r.workloads.add(stripPodSuffix(podName)); }
  if (image) r.images.add(image);
});

const pod_events = Object.values(byReason).map(r => ({
  reason: r.reason,
  count: r.count,
  distinct_pods: r.pods.size,
  distinct_workloads: r.workloads.size,
  workloads: Array.from(r.workloads).slice(0, 10),
  images: Array.from(r.images),
  sample_message: r.sample_message,
})).sort((a, b) => b.distinct_pods - a.distinct_pods);

const flags = pod_events
  .filter(r => r.distinct_pods > 0)
  .map(r => `${r.reason}: ${r.distinct_pods} pod(s) across ${r.distinct_workloads} workload(s)` + (r.images.length ? ` \u2014 image ${r.images[0]}` : ''))
  .slice(0, 8);

return [{ json: { pod_events, flags, ok: resp.error === undefined, source_error: resp.error || null }, pairedItem: { item: 0 } }];

// Surface GKE control-plane changes (cluster/node-pool upgrades, autoscaling/management changes)
// in the 6h before the incident. These trigger fleet-wide pod restarts/recreation and are
// invisible to Dynatrace (control-plane operations, not app-namespace events).
let resp = {};
try { resp = $('Get GKE Cluster Audit Log').first().json || {}; } catch (e) { resp = {}; }
const entries = Array.isArray(resp.entries) ? resp.entries : [];
const created = ($('Normalize Incidents').first().json.incident || {}).created_at;
const t0 = created ? Date.parse(created) : Date.now();

const cluster_changes = entries.map(e => {
  const pp = e.protoPayload || {};
  const method = (pp.methodName || '').split('.').pop() || pp.methodName;
  const target = (pp.resourceName || '').split('/').pop() || null;
  const ts = e.timestamp ? Date.parse(e.timestamp) : null;
  return {
    method,
    target,
    timestamp: e.timestamp || null,
    minutes_before_incident: ts ? Math.round((t0 - ts) / 60000) : null,
  };
}).sort((a, b) => (a.minutes_before_incident || 0) - (b.minutes_before_incident || 0));

const flags = cluster_changes.slice(0, 5).map(c =>
  `${c.method} on ${c.target || 'cluster'} started ~${c.minutes_before_incident}min before incident`
);

return [{ json: { cluster_changes, flags, ok: resp.error === undefined, source_error: resp.error || null }, pairedItem: { item: 0 } }];

// Resolve into RUM app entity ids; if none found (unrecognized-service incident, or no RUM app named after ccs-ratingprofile-gateway), skip the Grail call entirely rather than firing a query that can't scope to anything.
let entities = [];
try { entities = ($('Resolve RUM Application').first().json || {}).entities || []; } catch (e) { entities = []; }
let appIds = entities.map(e => e && e.entityId && e.entityId.id).filter(Boolean);
// If the name lookup returns nothing (e.g. the classic token lacks entities.read -> 403), use the configured RUM
// application entity id. A RUM app entity is stable: set it once (Dynatrace URL of the app, APPLICATION-...).
const RUM_APP_ID = 'YOUR_RUM_APPLICATION_ID';
if (!appIds.length && !/^YOUR_/.test(RUM_APP_ID)) appIds = [RUM_APP_ID];
const created = ($('Normalize Incidents').first().json.incident || {}).created_at;
const t0 = created ? Date.parse(created) : Date.now();
const fromIso = new Date(t0 - 30 * 60000).toISOString();
const toIso = new Date(t0 + 15 * 60000).toISOString();
const idList = appIds.map(id => `"${id}"`).join(', ');
const dql = appIds.length
  ? `fetch user.sessions | filter in(${idList}, dt.rum.application.entities) | summarize sessions = countDistinctExact(dt.rum.session.id), sessionsWithErrors = countIf(error.count > 0), sessionsWith5xx = countIf(error.http_5xx_count > 0), sessionsWith4xx = countIf(error.http_4xx_count > 0), sum5xx = sum(error.http_5xx_count), totalErrors = sum(error.count)`
  : null;
return { has_rum_app: appIds.length > 0, app_ids: appIds, dql, fromIso, toIso };

