try { hasApp = !!$('Build RUM Query').first().json.has_rum_app; } catch (e) { hasApp = false; }
if (!hasApp) return { has_rum_data: false, sessions: 0, sessions_with_errors: 0, sessions_with_5xx: 0, sessions_with_4xx: 0, error_rate_pct: null, flags: [] };
let resp = {};
try { resp = $json || {}; } catch (e) { resp = {}; }
const rec = (resp.result && Array.isArray(resp.result.records) && resp.result.records[0]) || {};
const sessions = Number(rec.sessions) || 0;
const sessionsWithErrors = Number(rec.sessionsWithErrors) || 0;
const sessionsWith5xx = Number(rec.sessionsWith5xx) || 0;
const sessionsWith4xx = Number(rec.sessionsWith4xx) || 0;
const errorRatePct = sessions > 0 ? Math.round((sessionsWithErrors / sessions) * 1000) / 10 : null;
const flags = [];
if (sessions > 0 && errorRatePct != null && errorRatePct >= 5) flags.push(`RUM: ${errorRatePct}% of ${sessions} real user sessions hit errors (${sessionsWith5xx} with 5xx)`);
if (sessions === 0) flags.push('RUM: 0 user sessions observed for this app in the incident window');
return {
  has_rum_data: true, ok: resp.error === undefined, source_error: resp.error || null,
  sessions, sessions_with_errors: sessionsWithErrors, sessions_with_5xx: sessionsWith5xx, sessions_with_4xx: sessionsWith4xx,
  error_rate_pct: errorRatePct, flags
};

// From the linked Dynatrace problem, split impacted entities into:
//  - cloudAppNames: CLOUD_APPLICATION entities = k8s workloads (free, no extra call)
//  - serviceIds: SERVICE entities that need one relationship hop to their CLOUD_APPLICATION
let problem = {};
try { problem = $('Get Linked Dynatrace Problem').first().json || {}; } catch (e) { problem = {}; }
const hasLinkedProblem = !!(problem && (problem.problemId || problem.displayId));

const cloudApps = new Set();
const serviceIds = new Set();
const scan = (ent) => {
  if (!ent) return;
  const e = ent.entityId ? ent : (ent.impactedEntity || ent.entity || null);
  if (!e || !e.entityId) return;
  const t = e.entityId.type, id = e.entityId.id, nm = e.name;
  if (t === 'CLOUD_APPLICATION' && nm) cloudApps.add(nm);
  else if (t === 'SERVICE' && id) serviceIds.add(id);
};
(problem.affectedEntities || []).forEach(scan);
(problem.impactedEntities || []).forEach(scan);
((problem.impactAnalysis || {}).impacts || []).forEach(scan);
scan(problem.rootCauseEntity);

const cloudAppNames = Array.from(cloudApps);
const svcIds = Array.from(serviceIds).slice(0, 20);
const needResolve = cloudAppNames.length === 0 && svcIds.length > 0;
// CLOUD_APPLICATIONs the affected SERVICE(s) run on. 'runsOn' relationship is env-specific — validated
// via a real run; onError:continue on the fetch means a wrong name just yields [] -> scan_wide fallback.
const entitySelector = needResolve
  ? `type(CLOUD_APPLICATION),fromRelationships.runsOn(type(SERVICE),entityId(${svcIds.map(id => `"${id}"`).join(',')}))`
  : 'type(CLOUD_APPLICATION),entityName("__lumen_none__")';
const DT_BASE = 'https://iyc06796.live.dynatrace.com';
const resolveUrl = DT_BASE + '/api/v2/entities?pageSize=200&entitySelector=' + encodeURIComponent(entitySelector);
// Grail path (platform token): SERVICE -runs_on-> PROCESS_GROUP -belongs_to-> CLOUD_APPLICATION (= k8s workload name).
let _created = null; try { _created = ($('Normalize Incidents').first().json.incident || {}).created_at; } catch (e) { _created = null; }
const _t0 = _created ? Date.parse(_created) : Date.now();
const fromIso = new Date(_t0 - 30 * 60000).toISOString();
const toIso = new Date(_t0 + 15 * 60000).toISOString();
const dql = needResolve
  ? 'fetch dt.entity.service | filter in(id, array(' + svcIds.map(id => '"' + id + '"').join(', ') + '))'
    + ' | fieldsAdd pg = runs_on[dt.entity.process_group]'
    + ' | lookup [ fetch dt.entity.process_group | filter isNotNull(belongs_to[dt.entity.cloud_application]) | fieldsAdd ca = belongs_to[dt.entity.cloud_application] | fields id, ca ], sourceField:pg, lookupField:id, fields:{ca}'
    + ' | expand ca'
    + ' | lookup [ fetch dt.entity.cloud_application | fields id, ca_name = entity.name ], sourceField:ca, lookupField:id, fields:{ca_name}'
    + ' | filter isNotNull(ca_name) | summarize workloads = collectDistinct(ca_name)'
  : null;
return [{ json: { hasLinkedProblem, cloudAppNames, serviceIds: svcIds, needResolve, entitySelector, resolveUrl, dql, fromIso, toIso }, pairedItem: { item: 0 } }];

