// Select the most-recent PD past incident matching the current alert signature (for resolution-note lookup).
const pastResp = (function(){ try { return $('Get PD Past Incidents').item.json || {}; } catch (e) { return {}; } })();
const inc = (function(){ try { return $('Normalize Incidents').item.json.incident || {}; } catch (e) { return {}; } })();
const pastList = Array.isArray(pastResp.past_incidents) ? pastResp.past_incidents : [];
const _sigOf = (t) => String(t || '').replace(/^\s*(OPEN|RESOLVED)?\s*Problem\s+P-[0-9]+:\s*/i, '').replace(/\s+/g, ' ').trim();
const _normSig = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim();
const _curKey = _normSig(_sigOf(inc.title || inc.summary || ''));
let last = 0, lastId = '';
pastList.forEach(function(pi){
  const it = (pi && pi.incident) || {};
  if (_curKey && _normSig(_sigOf(it.title)) !== _curKey) return;
  const ts = it.created_at ? new Date(it.created_at).getTime() : 0;
  if (!lastId || ts > last) { last = ts; lastId = String(it.id || ''); }
});
return { past_pick_id: lastId || '' };

const store = $getWorkflowStaticData('global');
store.seenResolved = store.seenResolved || {};
const now = Date.now();
const windowMs = 60 * 60 * 1000;
for (const k of Object.keys(store.seenResolved)) { if (now - store.seenResolved[k] > windowMs) delete store.seenResolved[k]; }
const out = [];
for (const item of $input.all()) {
  const id = String((item.json && item.json.incident_id) || '');
  if (!id) continue;
  if (store.seenResolved[id]) continue;
  store.seenResolved[id] = now;
  out.push(item);
}
return out;

const inc = (function(){ try { return $('Get Resolved Incident').item.json.incident || {}; } catch (e) { return {}; } })();
const ei = $('Extract Incident Context').item.json;
const num = String((inc.incident_number != null ? inc.incident_number : ei.incident_id)).replace(/[^0-9]/g, '');
const query_body = {
  query: "SELECT likely_root_cause, next_steps_json, root_cause_category, severity, confidence_score FROM `cio-converged-charging-np-72ca.lumen.triage_incidents` WHERE incident_number = '" + num + "' ORDER BY triaged_at DESC LIMIT 1",
  useLegacySql: false,
  location: "northamerica-northeast1",
  timeoutMs: 20000
};
return { query_body, incident_number_clean: num };

// Keep only substantive human resolution text: drop Lumen's own notes, process/status notes and link-only notes.
const _PROCESS = [/game ?(day|night)\b.*\b(ended|concluded|complete)/i, /notes? (will be |have been |were )?(captured|published)/i, /scribe agent/i, /triage artifact/i, /closed in dynatrace/i, /already cleared/i];
function cleanNote(c) {
  let s = String(c || '');
  const k = s.indexOf('Lumen Auto-Triage');
  if (k !== -1) s = s.slice(0, k).replace(/[|\s🟢🟡🔴]+$/u, '');
  s = s.trim();
  if (!s) return '';
  const noUrl = s.replace(/https?:\/\/\S+/g, '').replace(/^resolution note:\s*/i, '').trim();
  if (noUrl.length < 30) return '';
  if (_PROCESS.some(function (re) { return re.test(noUrl); }) && noUrl.length < 160) return '';
  return s;
}

const ei = $('Extract Incident Context').item.json;
const incResp = (function(){ try { return $('Get Resolved Incident').item.json || {}; } catch (e) { return {}; } })();
const inc = incResp.incident || incResp || {};
const notesResp = (function(){ try { return $('Get Resolution Notes').item.json || {}; } catch (e) { return {}; } })();
const rawNotes = (Array.isArray(notesResp.notes) ? notesResp.notes : []).map(function(n){ return String((n && n.content) || '').trim(); }).filter(function(c){ return c && c.indexOf('Lumen Auto-Triage') === -1; });
const notes = rawNotes.map(cleanNote).filter(Boolean);
const bq = (function(){ try { return $('Fetch Original Triage').item.json || {}; } catch (e) { return {}; } })();
const row0 = (bq.rows && bq.rows[0] && bq.rows[0].f) ? bq.rows[0].f.map(function(x){ return x && x.v; }) : [];
const orig = {
  likely_root_cause: row0[0] || '',
  next_steps: (function(){ try { return JSON.parse(row0[1] || '[]'); } catch (e) { return []; } })(),
  root_cause_category: row0[2] || '',
  severity: row0[3] || '',
  confidence_score: Number(row0[4]) || 0
};
const incNum = inc.incident_number != null ? Number(inc.incident_number) : Number(String(ei.incident_id));
let uid = Number(incNum);
if (!Number.isInteger(uid) || uid <= 0) { const s = String(inc.id || ei.incident_id || ''); let h = 0; for (let i = 0; i < s.length; i++) { h = (h * 31 + s.charCodeAt(i)) % 9007199254740880; } uid = h || 1; }
const createdAt = inc.created_at || null;
const resolvedAt = inc.resolved_at || inc.last_status_change_at || new Date().toISOString();
const mttrMin = (createdAt && resolvedAt) ? Math.round((new Date(resolvedAt) - new Date(createdAt)) / 60000) : null;
const resolution = notes.join(' | ').slice(0, 1000);
const predicted = (orig.next_steps || []).join(' | ');
const has_triage = !!String(orig.likely_root_cause).trim();
const has_resolution = resolution.length > 0;
const text = [inc.title || ei.incident_title, 'service: ' + (ei.service_name || ''), 'root cause: ' + orig.likely_root_cause, 'predicted next steps: ' + predicted, 'ACTUAL RESOLUTION: ' + (resolution || 'none recorded'), 'mttr_min: ' + mttrMin].filter(Boolean).join('\n').slice(0, 2000);
return {
  row_id: uid, embed_input: text, text,
  incident_id: String(ei.incident_id || inc.id || ''),
  incident_number: String(incNum || ''),
  incident_url: inc.html_url || ei.incident_url || '',
  service_focus: ei.service_name || '',
  root_cause_category: orig.root_cause_category, severity: orig.severity,
  confidence_score: orig.confidence_score, likely_root_cause: orig.likely_root_cause,
  predicted_next_steps: predicted, resolution_notes: resolution,
  resolution_note_count: notes.length, raw_note_count: rawNotes.length, resolved_at: resolvedAt,
  created_at: createdAt, mttr_minutes: mttrMin,
  has_triage: has_triage, has_resolution: has_resolution,
  // KB write + outcome scoring only when there is an original triage to compare AND a real human resolution.
  kb_useful: has_triage && has_resolution
};

const rec = $('Build KB Resolution').item.json;
const emb = ($json.data && $json.data[0] && $json.data[0].embedding) || null;
if (!emb) { return []; }
const row = {
  id: rec.row_id, vector: emb, text: rec.text, category: 'incident-triage',
  incident_id: rec.incident_id, service: rec.service_focus, severity: rec.severity,
  root_cause_category: rec.root_cause_category, likely_root_cause: rec.likely_root_cause,
  resolution_notes: rec.resolution_notes, resolution_status: 'resolved',
  resolved_at: rec.resolved_at || '', mttr_minutes: rec.mttr_minutes != null ? rec.mttr_minutes : 0,
  incident_url: rec.incident_url, created_at: rec.created_at || new Date().toISOString(), source: 'lumen'
};
const schema = {
  text: { type: 'string', full_text_search: true },
  category: { type: 'string', filterable: true },
  incident_id: { type: 'string', filterable: true },
  service: { type: 'string', filterable: true },
  severity: { type: 'string', filterable: true },
  root_cause_category: { type: 'string', filterable: true },
  resolution_status: { type: 'string', filterable: true },
  resolved_at: { type: 'string', filterable: true },
  mttr_minutes: { type: 'int', filterable: true },
  source: { type: 'string', filterable: true }
};
return { body: { upsert_rows: [row], distance_metric: 'cosine_distance', schema } };

