const raw = (($json.output ?? $json.text) ?? '').toString().trim();
let s = raw; const fence = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/i); if (fence) s = fence[1].trim();
let p = null; try { p = JSON.parse(s); } catch (e) { const m = raw.match(/\{[\s\S]*\}/); if (m) { try { p = JSON.parse(m[0]); } catch (e2) {} } }
const matched = (p && Number.isFinite(Number(p.matched))) ? Math.max(0, Math.min(1, Number(p.matched))) : null;
return { triage_matched_outcome: matched, match_rationale: (p && String(p.rationale || '')) || '' };

const r = $('Build KB Resolution').item.json;
const sc = (function(){ try { return $('Parse Outcome Score').item.json || {}; } catch (e) { return null; } })() || (r.kb_useful ? {} : { triage_matched_outcome: null, match_rationale: 'not scored: ' + (!r.has_triage ? 'no original triage' : 'no human resolution notes'), outcome_score_failed: false });
const S = v => (v == null ? '' : String(v));
const T = v => { const s = S(v); return s ? s : null; };
const nInt = v => { const x = parseInt(v, 10); return Number.isFinite(x) ? x : null; };
const nF = v => { const x = Number(v); return Number.isFinite(x) ? x : null; };
const row = {
  schema_version: 1,
  incident_id: S(r.incident_id), incident_number: S(r.incident_number), incident_url: S(r.incident_url),
  service_focus: S(r.service_focus), root_cause_category: S(r.root_cause_category), severity: S(r.severity),
  triage_confidence_score: nF(r.confidence_score),
  resolved_at: T(r.resolved_at), created_at: T(r.created_at), mttr_minutes: nInt(r.mttr_minutes),
  resolution_notes: S(r.resolution_notes), resolution_note_count: nInt(r.resolution_note_count),
  predicted_next_steps: S(r.predicted_next_steps),
  triage_matched_outcome: (sc.triage_matched_outcome == null ? null : nF(sc.triage_matched_outcome)), match_rationale: S(sc.match_rationale),
  recorded_at: new Date().toISOString()
};
const insertId = row.incident_number + '_' + (row.resolved_at || Date.now());
return [{ json: { bq_body: { rows: [ { insertId, json: row } ], skipInvalidRows: false, ignoreUnknownValues: true } } }];

// Guard: BigQuery insertAll returns HTTP 200 even when it rejects rows, and this
// insert node uses onError=continueRegularOutput — so failures were silently
// swallowed (execution showed "success"). Throw on any failure so the workflow's
// On Error -> Post Error to Slack path fires and the execution is marked failed.
const j = $json || {};
// 1) hard API error captured by continueRegularOutput (e.g. table not found, 4xx/5xx)
if (j.error) {
  const e = j.error;
  throw new Error('BigQuery insert failed: ' + (e.description || e.message || JSON.stringify(e)));
}
// 2) soft per-row rejects: 200 response carrying insertErrors
if (Array.isArray(j.insertErrors) && j.insertErrors.length) {
  throw new Error('BigQuery insertAll rejected ' + j.insertErrors.length +
    ' row(s): ' + JSON.stringify(j.insertErrors).slice(0, 600));
}
// success — pass through unchanged
return $input.all();

