const pd = $('Build PD Note').item.json;
let text = String(pd.note_content || '');
// Slack mrkdwn: bold the title line + section headers. Deterministic, no LLM involved
// (past bug: LLM-emitted multi-line markdown broke JSON.parse - see Build PD Note history).
const HEADERS = new Set(['Next steps:', 'Top failing endpoints:', '\ud83d\udd17 Links']);
const lines = text.split('\n');
if (lines.length) lines[0] = '*' + lines[0] + '*';
text = lines.map(l => HEADERS.has(l) ? '*' + l + '*' : l).join('\n');
return { gchat_text: text };

// Optional static service catalog (owning team, observed callers/callees, 7-day p95 baseline, chronic-error
// baseline) -- NOT live telemetry. Ships EMPTY: the lookup degrades to "No impacted service matched".
// To populate, paste a trimmed projection of your own service catalog. Record shape (short keys keep the node small):
//   s: [{ r: "service-name", d: ["k8s-deployment-name", ...], role: "...", crit: "critical|high|low", ev: "evidence level",
//         st: "status (omit if active)", sq: ["Owning team"], sqf: "why placed (if inferred)", calls: [...], by: [...],
//         p95: 845, req7d: 59700000, bg: 1 (blue/green on different releases), kfm: "known failure mode" }]
//   chronic: [{ svc: "service-name", re: "regex of a chronic background error", note: "why it is background noise" }]
//   nonrel:  ["X and Y do not depend on each other despite the similar name", ...]
//   esc:     "one-line escalation path"
// Worked example (TELUS Casa): catalog schema v2 in telus/carecx-agent-claude-skills
// casa-analyzer/casa-incident-context/casa-architecture-map.json -- see the Lumen Console /references page.
const SERVICE_CATALOG = {"v": "", "s": [], "chronic": [], "nonrel": [], "esc": ""};

function norm(name) {
  return String(name || '').toLowerCase()
    .replace(/-(green-)?(production|prod|pr)(-public|-v1)?(-.*)?$/, '')
    .replace(/-(training.*|green|canary|staging)$/, '')
    .replace(/-experience-api$/, '')
    .replace(/[^a-z0-9]/g, '');
}
const idx = {};
SERVICE_CATALOG.s.forEach(function (s) {
  [s.r].concat(s.d || []).forEach(function (n) { const k = norm(n); if (k && !idx[k]) idx[k] = s; });
});
function lookup(name) {
  const k = norm(name);
  return idx[k] || idx[k.replace(/bff$/, '')] || idx[k + 'bff'] || null;
}

let btc = {};
try { btc = $('Build Triage Context').item.json || {}; } catch (e) { btc = {}; }
const candidates = []
  .concat(btc.root_cause_service ? [btc.root_cause_service] : [])
  .concat(Array.isArray(btc.impacted_apps) ? btc.impacted_apps : [])
  .concat(Array.isArray(btc.error_log_services) ? btc.error_log_services : []);

const seen = new Set();
const matches = [];
candidates.forEach(function (name) {
  const hit = lookup(name);
  if (hit && !seen.has(hit.r)) { seen.add(hit.r); matches.push(Object.assign({ matched_on: String(name) }, hit)); }
});

// Chronic background errors: patterns present in multiple censuses weeks apart.
const sigText = []
  .concat(Array.isArray(btc.error_signatures) ? btc.error_signatures : [])
  .concat((Array.isArray(btc.error_logs) ? btc.error_logs : []).slice(0, 50).map(function (l) {
    return typeof l === 'string' ? l : [l.service, l.content, l.message, l.text, l.textPayload].filter(Boolean).join(' ');
  }))
  .join('\n');
const chronicHits = SERVICE_CATALOG.chronic.filter(function (c) {
  try { return new RegExp(c.re).test(sigText); } catch (e) { return false; }
});

function fmt(m) {
  const L = [];
  L.push('- ' + m.r + ' (matched "' + m.matched_on + '")' + (m.st ? '  ** STATUS: ' + m.st + ' **' : ''));
  L.push('  criticality: ' + (m.crit || 'unknown') + (m.cl ? ' | cluster: ' + m.cl : '') + ' | evidence: ' + m.ev);
  if (m.role) L.push('  role: ' + m.role);
  if (m.sq) L.push('  owning team: ' + m.sq.join(', ') + (m.sqf ? ' -- placement inferred: ' + m.sqf + ' (confirm with squad lead)' : ''));
  else L.push('  owning team: unknown -- route via the escalation policy');
  if (m.by) L.push('  observed callers (upstream blast radius if this degrades): ' + m.by.join(', '));
  if (m.calls) L.push('  observed downstream calls (possible upstream root cause): ' + m.calls.join(', '));
  if (m.p95) L.push('  7d baseline: p95 ' + m.p95 + ' ms, ' + m.req7d.toLocaleString('en-US') + ' requests/7d');
  if (m.bg) L.push('  blue/green on different releases (normal between deploys; green only takes header-opted traffic)');
  if (m.gov) L.push('  governance flag: ' + m.gov);
  if (m.kfm) L.push('  known failure mode: ' + m.kfm);
  return L.join('\n');
}

const nonRel = SERVICE_CATALOG.nonrel.filter(function (r) { return matches.some(function (m) { return r.indexOf(m.r) !== -1; }); });
const parts = [];
if (matches.length) {
  parts.push('Static service catalog reference for the impacted service(s) (catalog ' + SERVICE_CATALOG.v + '; facts, not live telemetry):\n' + matches.map(fmt).join('\n'));
} else {
  parts.push('No impacted service matched the static service catalog.');
}
if (chronicHits.length) {
  parts.push('Chronic background errors present in this window -- seen in multiple error censuses weeks apart; do NOT cite as root cause unless clearly spiking vs. normal:\n- '
    + chronicHits.map(function (c) { return c.svc + ': /' + c.re + '/ -- ' + c.note; }).join('\n- '));
}
if (nonRel.length) parts.push('Known non-relationships (avoid false blast-radius assumptions):\n- ' + nonRel.join('\n- '));
if (SERVICE_CATALOG.esc) parts.push('Escalation: ' + SERVICE_CATALOG.esc);

return {
  architecture_matches: matches,
  architecture_chronic_hits: chronicHits.map(function (c) { return c.svc + ' /' + c.re + '/'; }),
  architecture_context: parts.join('\n\n')
};

const b = $('Build Triage Context').item.json;
const rec = b.service_recognition || {};
if (rec.is_recognized_service !== false) {
  return { skip: true, search_words: [], dql: 'fetch dt.entity.service | filter false | limit 1' };
}
// Best-effort keyword extraction -- prefer the incident's own DESCRIPTION (the actual technical
// report) over pd_service_name, which is often just a generic team/queue label (e.g. "CIO PEX
// Incidents") that is never a real Dynatrace entity name and would otherwise crowd out better
// candidates pulled from the ticket text.
const _stop = new Set(['the', 'a', 'an', 'api', 'service', 'and', 'or', 'for', 'with', 'from', 'of', 'to', 'in', 'on', 'is', 'threat', 'bff']);
function capRuns(text) {
  const words = String(text || '').replace(/[^\w\s-]/g, ' ').split(/\s+/).filter(Boolean);
  const runs = []; let run = [];
  for (const w of [...words, '']) {
    if (/^[A-Z][A-Za-z0-9]*$/.test(w) && !_stop.has(w.toLowerCase())) {
      run.push(w);
    } else {
      if (run.length) runs.push(run);
      run = [];
    }
  }
  return runs;
}
const descRuns = capRuns(rec.incident_description);
const nameRuns = descRuns.length ? [] : capRuns(rec.pd_service_name); // only fall back if description gave nothing
const allRuns = descRuns.length ? descRuns : nameRuns;
const best = allRuns.reduce((a, r) => (r.length > (a ? a.length : 0) ? r : a), null);
if (!best) return { skip: true, search_words: [], dql: 'fetch dt.entity.service | filter false | limit 1' };

// Dynatrace service names are code identifiers (PascalCase/underscored, no spaces) -- search on
// individual significant words rather than the literal multi-word phrase, which would never match.
const words = [...new Set(best.filter(w => w.length >= 4))].slice(0, 4);
if (!words.length) return { skip: true, search_words: [], dql: 'fetch dt.entity.service | filter false | limit 1' };
const esc = w => w.replace(/"/g, '\\"');
const clauses = words.map(w => 'contains(entity.name, "' + esc(w) + '")').join(' or ');
return {
  skip: false,
  search_words: words,
  dql: 'fetch dt.entity.service | filter ' + clauses + ' | fields id, entity.name | limit 20'
};

const searchInfo = $('Extract External Search Terms').item.json;
if (searchInfo.skip) return { external_entity_match: null };
let records = [];
try { records = ($json.result && $json.result.records) || []; } catch (e) {}
const words = searchInfo.search_words || [];
if (!records.length || !words.length) return { external_entity_match: null, search_words: words };
// Rank by how many search words each candidate's name actually contains (case-insensitive) --
// more word hits = a stronger, more specific match. Ties broken by shorter name (less likely to be
// a coincidental substring hit inside an unrelated, longer name).
function score(name) {
  const n = String(name || '').toLowerCase();
  return words.reduce((c, w) => c + (n.includes(w.toLowerCase()) ? 1 : 0), 0);
}
records.forEach(r => { r.__score = score(r['entity.name']); });
records.sort((a, b) => (b.__score - a.__score) || (String(a['entity.name'] || '').length - String(b['entity.name'] || '').length));
const top = records[0];
if (!top || !top.__score) return { external_entity_match: null, search_words: words };
return {
  external_entity_match: {
    id: top.id,
    name: top['entity.name'],
    match_score: top.__score,
    candidate_count: records.length,
    search_words: words
  }
};

// BigQuery jobs.query REST response: rows as [{f:[{v},...]}], field names in schema.fields order.
const resp = $json || {};
const fields = (resp.schema && resp.schema.fields) || [];
const rows = resp.rows || [];
const dynamic_noise = rows.map(r => {
  const obj = {};
  (r.f || []).forEach((cell, i) => { if (fields[i]) obj[fields[i].name] = cell.v; });
  return {
    endpoint: obj.endpoint || null,
    incident_count: Number(obj.incident_count) || 0,
    category_diversity: Number(obj.category_diversity) || 0
  };
}).filter(x => x.endpoint);
return { dynamic_noise };

// Same shape as GameDaySummary-v2's "Resolve Situation Room ID" -- GET /incidents?pagerduty_id=...
// returns { data: [...], meta } (documented IRIS Public API filter, confirmed via a real execution).
const resp = $('IRIS Incident Details').first().json || {};
const rows = Array.isArray(resp.data) ? resp.data : (resp.data ? [resp.data] : []);
const inc = rows[0] || null;
return { irisIncidentId: inc ? (inc.id || '') : '', irisMatched: !!inc };

const _listResp = $('IRIS Incident Details').first().json;
let _listRow = Array.isArray(_listResp) ? (_listResp[0] || {}) : ((_listResp && Array.isArray(_listResp.data)) ? (_listResp.data[0] || {}) : ((_listResp && (_listResp.data || (_listResp.output && _listResp.output.data))) || _listResp || {}));
if (Array.isArray(_listRow)) _listRow = _listRow[0] || {};

const _irisId = ($('Resolve IRIS Incident Id').item.json || {}).irisIncidentId || '';

// Prefer the dedicated report endpoint's normalized schema (same shape confirmed working in
// PERF-GameDaySummary-v2's Extract IRIS Notes):
// { data: { ai_root_cause, manual_root_cause, ai_executive_summary, manual_executive_summary,
//           action_items[], actions_taken[], lessons_learned[], timeline_events[], links[] } }
// Every child row follows a manual_X (human override) ?? ai_X (generated) pattern.
const _reportResp = $('Get IRIS Incident Report').first().json || {};
const d = (_reportResp.data && typeof _reportResp.data === 'object' && !Array.isArray(_reportResp.data)) ? _reportResp.data : null;

const clip = (s, n) => { s = (typeof s === 'string') ? s : JSON.stringify(s || ''); return s.length > n ? s.slice(0, n) + ' ...[truncated]' : s; };
const pick = (row, manualKey, aiKey) => (row && row[manualKey]) || (row && row[aiKey]) || '';

// Fallback: the list row's cached ai_report (camelCase) if the dedicated report call failed/404'd.
const airFallback = _listRow.ai_report || {};

if (!d && !_listRow.id && !airFallback.rootCause && !airFallback.executiveSummary) {
  return { iris_notes: 'Unavailable (IRIS not configured or no incident matched).', iris_notes_available: false, iris_primes: '', iris_incident_id: _irisId, iris_web_url: '' };
}

const rc = d ? pick(d, 'manual_root_cause', 'ai_root_cause') : (airFallback.rootCause || '');
const exec = d ? pick(d, 'manual_executive_summary', 'ai_executive_summary') : (airFallback.executiveSummary || '');

const lessons = d
  ? (d.lessons_learned || []).map(l => ((l.category === 'needs_improvement' ? '(!) ' : '(+) ') + pick(l, 'manual_lesson', 'ai_lesson'))).filter(x => x && x.length > 4)
  : [].concat(
      ((airFallback.lessonsLearned && airFallback.lessonsLearned.wentWell) || []).map(x => '(+) ' + x),
      ((airFallback.lessonsLearned && airFallback.lessonsLearned.needsImprovement) || []).map(x => '(!) ' + x)
    );

const actions = d
  ? (d.action_items || []).map(a => {
      const title = pick(a, 'manual_title', 'ai_title');
      const desc = pick(a, 'manual_description', 'ai_description');
      const pr = pick(a, 'manual_priority', 'ai_priority');
      return title ? `[${pr || '-'}] ${title}${desc ? ': ' + desc : ''}` : '';
    }).filter(Boolean)
  : (airFallback.actionItems || []).map(a => `[${a.priority || '-'}] ${a.title || ''}${a.description ? ': ' + a.description : ''}`);

const actionsTaken = d
  ? (d.actions_taken || []).map(a => pick(a, 'manual_action', 'ai_action')).filter(Boolean)
  : (airFallback.actionsTaken || []);

const parts = [];
if (exec) parts.push('Exec summary: ' + clip(exec, 1500));
if (rc) parts.push('Root cause: ' + clip(rc, 800));
if (lessons.length) parts.push('Lessons:\n' + lessons.slice(0, 8).join('\n'));
if (actions.length) parts.push('Action items:\n' + actions.slice(0, 8).map(a => '- ' + a).join('\n'));
if (actionsTaken.length) parts.push('Actions taken:\n' + actionsTaken.slice(0, 8).map(a => '- ' + a).join('\n'));

const primes = [_listRow.issue_owner && ('owner ' + _listRow.issue_owner), _listRow.issue_director && ('director ' + _listRow.issue_director), _listRow.issue_vp && ('VP ' + _listRow.issue_vp)].filter(Boolean).join(', ');
if (primes) parts.push('Primes: ' + primes);

return {
  iris_notes: parts.length ? parts.join('\n\n') : 'No IRIS notes/report captured for this incident.',
  iris_notes_available: parts.length > 0,
  iris_primes: primes,
  iris_incident_id: _irisId,
  iris_web_url: _irisId ? ('https://iris.telus.com/incidents/' + _irisId + '/report') : ''
};

// Same BigQuery jobs.query REST response shape as Parse Endpoint Noise Stats.
const resp = $json || {};
const fields = (resp.schema && resp.schema.fields) || [];
const rows = resp.rows || [];
const catalog = rows.map(r => {
  const obj = {};
  (r.f || []).forEach((cell, i) => { if (fields[i]) obj[fields[i].name] = cell.v; });
  return { s: obj.service || null, f: obj.file || null };
}).filter(x => x.s && x.f);
return { runbook_catalog: catalog };
